import os, glob

root = r"C:/Users/Derek/Desktop/heretek-swarm"
src = os.path.join(root, "heretek_swarm", "actors")

# Find agent/actor constructors
for f in sorted(glob.glob(os.path.join(src, "**", "*.py"), recursive=True)):
