    try:
        with open(f) as fh:
            content = fh.read()
        if "__init__" in content:
            lines = content.split("\n")
            print(f"\n=== {rel} ===")
            for i, line in enumerate(lines):
                stripped = line.strip()
                if stripped.startswith("class ") or "def __init__" in stripped or "def __init__" in stripped:
                    print(f"  L{i+1}: {stripped}")
    except Exception as e:
        print(f"{rel}: ERROR {e}")
